# 5.4 — wevtutil và các lệnh thời cmd: KHÔNG chạy được ngoài Windows. Phần chạy thật ở đây: dấu vết những lệnh đó để lại trong log mẫu công khai (4688).
# tc/clear-4688-native.evtx (EVTX-to-MITRE-Attack: xoá mọi log bằng vòng for + wevtutil cl), mau/security_big_sample.evtx (máy chủ Nhật, 4688 không có CommandLine).
@ps Get-WinEventMau tc/clear-4688-native.evtx -Oldest -MaxEvents 6 | ForEach-Object { '{0:HH:mm:ss.fff}  {1}  {2}' -f $_.TimeCreated, $_.Properties[1].Value, $_.Properties[8].Value }
@ps $p = Get-WinEventMau tc/clear-4688-native.evtx | Where-Object { $_.Properties[5].Value -like '*wevtutil.exe' }; '{0} lần wevtutil, {1:HH:mm:ss.fff} → {2:HH:mm:ss.fff}' -f $p.Count, ($p.TimeCreated | Measure-Object -Minimum).Minimum, ($p.TimeCreated | Measure-Object -Maximum).Maximum
@ps Get-WinEventMau tc/clear-4688-native.evtx -MaxEvents 1 | ForEach-Object { ([xml]$_.ToXml()).Event.EventData.Data | Format-Table Name, '#text' -AutoSize }
@ps Get-WinEventMau mau/security_big_sample.evtx -FilterXPath "*[System[EventID=4688]]" | Group-Object { ($_.Properties[5].Value -split '\\')[-1] } | Sort-Object Count -Descending | Select-Object -First 8 Count, Name | Format-Table -AutoSize
@ps $w = Get-WinEventMau mau/security_big_sample.evtx -FilterXPath "*[System[EventID=4688]]" | Where-Object { $_.Properties[5].Value -like '*wevtutil.exe' }; $w | Select-Object -First 1 | ForEach-Object { ([xml]$_.ToXml()).Event.EventData.Data | Format-Table Name, '#text' -AutoSize }
@ps $w = Get-WinEventMau mau/security_big_sample.evtx -FilterXPath "*[System[EventID=4688]]" | Where-Object { $_.Properties[5].Value -like '*wevtutil.exe' }; $w | Group-Object { $_.TimeCreated.ToString('yyyy-MM-dd HH:00') } | Select-Object -First 6 Count, Name | Format-Table -AutoSize
@ps Get-WinEventMau -FilterHashtable @{ Path = 'mau/security_big_sample.evtx'; Id = 1102 } | Format-List TimeCreated, Id, @{n='SubjectUserName'; e={$_.Properties[1].Value}}, @{n='SubjectLogonId'; e={$_.Properties[3].Value}}
@ps Get-WinEventMau -FilterHashtable @{ Path = 'mau/security_big_sample.evtx'; Id = 4688; StartTime = [datetime]'2016-10-06 01:47:00'; EndTime = [datetime]'2016-10-06 01:47:10' } | Group-Object { ($_.Properties[5].Value -split '\\')[-1] }, { $_.Properties[3].Value } | Format-Table Count, Name -AutoSize
@ps (Get-WinEventMau mau/security_big_sample.evtx -Oldest -MaxEvents 1).TimeCreated.ToString('yyyy-MM-dd HH:mm:ss.fff')
@ps Get-WinEventMau -FilterHashtable @{ Path = 'mau/dbc-many-events-security.evtx'; Id = 4688 } | Group-Object MachineName, Version, { if ($_.Properties.Count -gt 8 -and $_.Properties[8].Value) { 'có CommandLine' } else { 'không CommandLine' } } | Format-Table Count, Name -AutoSize
